#!/usr/bin/env node
// Multilingual find recall: the same questions asked in 11 languages, ranked by
// the shipped `find`, with and without `--terms`.
//
// Corpus (cases/*.json, see README.md): 12 question sets × 5 questions × 11
// languages, plus one English `terms` string per question and language — what
// a calling agent would pass. English and French questions come from source
// eval cases; every other question and every terms string was generated by an
// open-weights model (glm-5.3-flash) and is copied verbatim.
//
// A question is a HIT when one of its case's expected files is among the first
// K_FILES files `find` returns: the `open:` files of its matched rows, in output
// order, deduped. K_FILES = 8 is find's default output — 8 modules (--k) of at
// most 8 files each, so 8 files is the first row's full list and never more
// than an agent opening "the top hit" reads. Graph-context rows (`via: graph`,
// score 0) matched nothing and are not counted.
//
// Gate: with --terms, every language's recall ≥ (English recall without terms)
// − 2 points. Exits 1 otherwise.
//
// Usage: node evals/multilingual/run.mjs [--json] [--write-readme]

import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(HERE, "..", "..");
const CLI = join(REPO_ROOT, "scripts", "ultraindex.mjs");
// The library bundle: built from the same src/ as the CLI in the same build.
// `runFindHybrid(out, q, k, repo, terms)` is exactly the call `find` makes,
// run in-process so 1 320 queries take seconds, not a node start each.
const LIB = join(REPO_ROOT, "scripts", "engine.mjs");

export const LANGS = ["en", "fr", "es", "de", "it", "pt", "nl", "ja", "zh", "ar", "ru"];
export const K_FILES = 8;
const FIND_K = 8; // find's default --k
const GATE_POINTS = 2;

const args = process.argv.slice(2);
const asJson = args.includes("--json");
const writeReadme = args.includes("--write-readme");

const cases = readdirSync(join(HERE, "cases"))
  .filter((f) => f.endsWith(".json"))
  .sort()
  .map((f) => JSON.parse(readFileSync(join(HERE, "cases", f), "utf8")));

const { runFindHybrid } = await import(pathToFileURL(LIB).href);

const tmp = mkdtempSync(join(tmpdir(), "ultraindex-ml-eval-"));
try {
  // One index per fixture, built by the shipped CLI.
  const indexOf = new Map();
  for (const fixture of [...new Set(cases.map((c) => c.fixture))].sort()) {
    const repo = join(HERE, "fixtures", fixture);
    const out = join(tmp, fixture);
    const r = spawnSync(process.execPath, [CLI, "build", "--repo", repo, "--out", out], { encoding: "utf8" });
    if (r.status !== 0) throw new Error(`build ${fixture} failed:\n${r.stderr}`);
    indexOf.set(fixture, { repo, out });
  }

  const topFiles = (results) => {
    const files = [];
    for (const row of results) {
      if (row.score <= 0) continue; // graph context, not a match
      for (const f of row.files) if (!files.includes(f)) files.push(f);
    }
    return files.slice(0, K_FILES);
  };

  const tally = {};
  const misses = [];
  for (const lang of LANGS) tally[lang] = { total: 0, plain: 0, terms: 0 };
  for (const c of cases) {
    const { repo, out } = indexOf.get(c.fixture);
    for (const lang of LANGS) {
      for (let i = 0; i < c.questions[lang].length; i++) {
        const q = c.questions[lang][i];
        const t = c.terms[lang][i];
        const plain = topFiles((await runFindHybrid(out, q, FIND_K, repo)).results);
        const bridged = topFiles((await runFindHybrid(out, q, FIND_K, repo, t)).results);
        const hitPlain = c.expect.files.some((f) => plain.includes(f));
        const hitTerms = c.expect.files.some((f) => bridged.includes(f));
        tally[lang].total++;
        if (hitPlain) tally[lang].plain++;
        if (hitTerms) tally[lang].terms++;
        if (!hitTerms) misses.push({ case: c.id, lang, question: q, terms: t, got: bridged });
      }
    }
  }

  const pct = (n, d) => Math.round((1000 * n) / d) / 10;
  const rows = LANGS.map((lang) => ({
    lang,
    questions: tally[lang].total,
    plain: pct(tally[lang].plain, tally[lang].total),
    terms: pct(tally[lang].terms, tally[lang].total),
  }));
  const floor = Math.round((rows[0].plain - GATE_POINTS) * 10) / 10;
  const failing = rows.filter((r) => r.terms < floor);

  const table = [
    `| language | questions | recall without --terms | recall with --terms |`,
    `| --- | ---: | ---: | ---: |`,
    ...rows.map((r) => `| ${r.lang} | ${r.questions} | ${r.plain.toFixed(1)}% | ${r.terms.toFixed(1)}% |`),
  ].join("\n");

  if (asJson) {
    process.stdout.write(JSON.stringify({ kFiles: K_FILES, floor, rows, misses, ok: failing.length === 0 }, null, 2) + "\n");
  } else {
    process.stdout.write(
      [
        `multilingual find recall — ${cases.length} cases, ${LANGS.length} languages, hit = expected file in the top ${K_FILES} files`,
        "",
        table,
        "",
        `gate: with --terms, every language ≥ English without terms (${rows[0].plain.toFixed(1)}%) − ${GATE_POINTS} = ${floor.toFixed(1)}%`,
        failing.length ? `FAIL: ${failing.map((r) => `${r.lang} ${r.terms.toFixed(1)}%`).join(", ")}` : "ok",
        "",
      ].join("\n"),
    );
  }

  if (writeReadme) {
    const path = join(HERE, "README.md");
    const readme = readFileSync(path, "utf8");
    const start = "<!-- results:start -->";
    const end = "<!-- results:end -->";
    const i = readme.indexOf(start);
    const j = readme.indexOf(end);
    if (i < 0 || j < i) throw new Error("README.md has no results markers");
    const block = `${start}\n${table}\n\nGate floor: ${floor.toFixed(1)}% (English without terms − ${GATE_POINTS} points).\n${end}`;
    writeFileSync(path, readme.slice(0, i) + block + readme.slice(j + end.length));
  }

  process.exitCode = failing.length ? 1 : 0;
} finally {
  rmSync(tmp, { recursive: true, force: true });
}
